function setHeight(value:number){if(coop.joined&&!coop.host){feedback='Host adjusts the shared station height.';return;}station.position.y=T.MathUtils.clamp(value,-.4,.3);plane.constant=-(1.08+station.position.y);(document.querySelector('#height') as HTMLInputElement).value=String(station.position.y);}
